import { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import Login from "./pages/Login";
import Register from "./pages/Register";
import DashboardProfesor from "./components/DashboardProfesor";
import DashboardAlumno from "./components/DashboardAlumno";
import InvitacionClase from "./components/alumno/InvitacionClase";

function App() {
  const [user, setUser] = useState(null);

  return (
    <Router>
      <Routes>
        {/* Página raíz: Login o redirección según el rol */}
        <Route
          path="/"
          element={
            !user ? (
              <Login onLogin={setUser} />
            ) : user.rol === "profesor" ? (
              <Navigate to="/dashboard-profesor" />
            ) : (
              <Navigate to="/dashboard-alumno" />
            )
          }
        />

        {/* Registro */}
        <Route path="/register" element={<Register />} />

        {/* Panel Profesor */}
        <Route
          path="/dashboard-profesor"
          element={
            user && user.rol === "profesor" ? (
              <DashboardProfesor user={user} />
            ) : (
              <Navigate to="/" />
            )
          }
        />

        {/* Panel Alumno (completo, con sidebar y mis clases) */}
        <Route
          path="/dashboard-alumno"
          element={
            user && user.rol === "alumno" ? (
              <DashboardAlumno user={user} onLogout={() => setUser(null)} />
            ) : (
              <Navigate to="/" />
            )
          }
        />

        {/* Ruta para invitación a clase */}
        <Route
          path="/invitar/:idClase"
          element={
            user && user.rol === "alumno" ? (
              <InvitacionClase />
            ) : (
              // Si el usuario NO es alumno o no está logueado, redirige al login
              <Navigate to="/" />
            )
          }
        />
      </Routes>
    </Router>
  );
}

export default App;
